#!/usr/bin/env python3
"""Generate src/accel/fe25519_mul.inc: field multiply and square mod 2^255-19
with ten signed limbs of alternately 26 and 25 bits (limb k starts at bit
ceil(25.5 k)), the layout of the ref10 code.

The product f_i * g_j lands at bit p(i) + p(j). That is p(i+j) + 1 when i and
j are both odd (so the term is doubled), p(i+j) otherwise; for i+j >= 10 it
wraps to limb i+j-10 times 2^255 = 19 (mod p). Generating the terms from this
rule keeps the 100 hand-copied products of the classic code out of review.

Operand scaling keeps every factor in 32 bits for limbs below 1.65*2^26 (even)
/ 1.65*2^25 (odd), the bounds the ladder guarantees after one add or sub:
multiply: the 2 goes on f_i (odd i), the 19 on g_j; square: the 2 of the
off-diagonal pair on f_i, the odd-odd 2 and the 19 on f_j (38 f_j only for odd
j, a 25-bit limb). Usage: python tools/gen_fe25519.py > src/accel/fe25519_mul.inc

With --base-table it writes src/accel/ge25519_base.inc instead: for the
fixed-base multiplication on the twisted Edwards form of Curve25519
(-x^2 + y^2 = 1 + d x^2 y^2, base point y = 4/5), the points j * 256^i * B
for i = 0..31, j = 1..8 as (y+x, y-x, 2dxy), canonical limbs, computed here
with exact integer arithmetic.
"""
import sys

P = 2**255 - 19
D = -121665 * pow(121666, P - 2, P) % P


def ed_add(a, b):
    (x1, y1), (x2, y2) = a, b
    t = D * x1 * x2 * y1 * y2 % P
    x3 = (x1 * y2 + y1 * x2) * pow(1 + t, P - 2, P) % P
    y3 = (y1 * y2 + x1 * x2) * pow(1 - t, P - 2, P) % P
    return x3, y3


def base_point():
    y = 4 * pow(5, P - 2, P) % P
    x2 = (y * y - 1) * pow(D * y * y + 1, P - 2, P) % P
    x = pow(x2, (P + 3) // 8, P)
    if x * x % P != x2:
        x = x * pow(2, (P - 1) // 4, P) % P
    assert x * x % P == x2
    if x & 1:
        x = P - x
    return x, y


def limbs(v):
    out = []
    for k in range(10):
        bits = 26 if k % 2 == 0 else 25
        out.append(v & ((1 << bits) - 1))
        v >>= bits
    assert v == 0
    return out


def base_table():
    print("/* Generated by tools/gen_fe25519.py --base-table; do not edit. */")
    print("static const ge_precomp k_base[32][8] = {")
    row = base_point()
    for i in range(32):
        print("    {")
        pt = row
        for j in range(8):
            x, y = pt
            parts = [(y + x) % P, (y - x) % P, 2 * D * x * y % P]
            print("        {" + ", ".join("{" + ", ".join(str(l) for l in limbs(v)) + "}" for v in parts) + "},")
            pt = ed_add(pt, row)
        print("    },")
        for _ in range(8):  # row *= 256
            row = ed_add(row, row)
    print("};")


def mul_terms():
    rows = [[] for _ in range(10)]
    for i in range(10):
        for j in range(10):
            k = i + j
            left = f"f{i}_2" if (i % 2 and j % 2) else f"f{i}"
            right = f"g{j}_19" if k >= 10 else f"g{j}"
            rows[k % 10].append(f"(int64_t){left} * {right}")
    return rows


def sq_terms():
    rows = [[] for _ in range(10)]
    for i in range(10):
        for j in range(i, 10):
            k = i + j
            left = f"f{i}_2" if i < j else f"f{i}"
            factor = (2 if (i % 2 and j % 2) else 1) * (19 if k >= 10 else 1)
            right = f"f{j}" if factor == 1 else f"f{j}_{factor}"
            rows[k % 10].append(f"(int64_t){left} * {right}")
    return rows


def used(rows, prefix):
    names = set()
    for row in rows:
        for term in row:
            for part in term.replace("(int64_t)", "").split(" * "):
                if part.startswith(prefix) and "_" in part:
                    names.add(part)
    return sorted(names, key=lambda n: (int(n[1:].split("_")[0]), int(n.split("_")[1])))


def emit(name, args, rows, scaled):
    out = [f"static void {name}({args}) {{"]
    out.append("    " + " ".join(f"int32_t f{i} = f[{i}];" for i in range(10)))
    if name == "fe_mul":
        out.append("    " + " ".join(f"int32_t g{i} = g[{i}];" for i in range(10)))
    for s in scaled:
        base, factor = s.split("_")
        out.append(f"    int32_t {s} = {factor} * {base};")
    for k, row in enumerate(rows):
        out.append(f"    int64_t h{k} = " + "\n        + ".join(row) + ";")
    out.append("    fe_carry_wide(h, h0, h1, h2, h3, h4, h5, h6, h7, h8, h9);")
    out.append("}")
    return "\n".join(out)


def main():
    m = mul_terms()
    s = sq_terms()
    print("/* Generated by tools/gen_fe25519.py; do not edit. */")
    print(emit("fe_mul", "fe h, const fe f, const fe g", m, used(m, "f") + used(m, "g")))
    print()
    print(emit("fe_sq", "fe h, const fe f", s, used(s, "f")))


if __name__ == "__main__":
    if sys.argv[1:] == ["--base-table"]:
        base_table()
    else:
        main()
